package corpus

import (
	"crypto/sha256"
	"encoding/binary"
)

// RNG is a SplitMix64 generator. It is implemented here, not taken from
// math/rand, so generated bytes cannot change with the Go release.
type RNG struct{ s uint64 }

// NewRNG derives an independent stream from a seed and a label.
func NewRNG(seed uint64, label string) *RNG {
	h := sha256.Sum256([]byte(label))
	return &RNG{s: seed ^ binary.LittleEndian.Uint64(h[:8])}
}

func (r *RNG) U64() uint64 {
	r.s += 0x9e3779b97f4a7c15
	z := r.s
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

// Intn returns a value in [0,n); n must be positive.
func (r *RNG) Intn(n int) int { return int(r.U64() % uint64(n)) }

func (r *RNG) Fill(b []byte) {
	for i := 0; i < len(b); {
		v := r.U64()
		for j := 0; j < 8 && i < len(b); j++ {
			b[i] = byte(v)
			v >>= 8
			i++
		}
	}
}

func (r *RNG) Bytes(n int) []byte {
	b := make([]byte, n)
	r.Fill(b)
	return b
}

// Perm returns a deterministic permutation of [0,n).
func (r *RNG) Perm(n int) []int {
	p := make([]int, n)
	for i := range p {
		p[i] = i
	}
	for i := n - 1; i > 0; i-- {
		j := r.Intn(i + 1)
		p[i], p[j] = p[j], p[i]
	}
	return p
}

var vocab = func() []string {
	r := NewRNG(0x5a33, "vocab")
	w := make([]string, 512)
	for i := range w {
		b := make([]byte, 2+r.Intn(8))
		for j := range b {
			b[j] = 'a' + byte(r.Intn(26))
		}
		w[i] = string(b)
	}
	return w
}()

// Text returns n bytes of skewed-vocabulary text (compressible, ~3x with DEFLATE).
func Text(r *RNG, n int) []byte {
	b := make([]byte, 0, n+16)
	for len(b) < n {
		i := min(r.Intn(len(vocab)), r.Intn(len(vocab)))
		b = append(b, vocab[i]...)
		switch r.Intn(12) {
		case 0:
			b = append(b, '\n')
		case 1:
			b = append(b, ", "...)
		default:
			b = append(b, ' ')
		}
	}
	return b[:n]
}
